package com.robot.platform.ai;
import com.robot.platform.integration.AbstractRobotPlatformIntegrationTest;import com.robot.platform.ai.conversation.dal.dataobject.*;import com.robot.platform.ai.conversation.dal.mysql.*;import com.robot.platform.ai.realtime.dal.dataobject.AiRealtimeSessionDO;import com.robot.platform.ai.realtime.dal.mysql.AiRealtimeSessionMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import java.time.LocalDateTime;import static org.assertj.core.api.Assertions.assertThat;
class AiRealtimeTraceIntegrationTest extends AbstractRobotPlatformIntegrationTest{@Autowired AiConversationMapper conversations;@Autowired AiConversationMessageMapper messages;@Autowired AiRealtimeSessionMapper sessions;
@Test void traceKeepsRouteModelOrderAndInterruptCountWithoutSecretsOrAudio(){long t=303L;AiConversationDO c=new AiConversationDO();c.setTenantId(t);c.setAgentId(1L);c.setRobotId(2L);c.setChannel("ROBOT_VOICE");c.setStatus("ACTIVE");c.setStartedAt(LocalDateTime.now());c.setCreatedAt(LocalDateTime.now());c.setUpdatedAt(LocalDateTime.now());conversations.insert(c);add(t,c.getId(),"turn-1","USER","hello",null);add(t,c.getId(),"turn-1","ASSISTANT","hi",88L);AiRealtimeSessionDO s=new AiRealtimeSessionDO();s.setTenantId(t);s.setConversationId(c.getId());s.setAgentId(1L);s.setRobotId(2L);s.setMode("NATIVE");s.setModelId(88L);s.setConnectedAt(LocalDateTime.now());s.setInterruptCount(1);s.setStatus("CLOSED");s.setCreatedAt(LocalDateTime.now());s.setUpdatedAt(LocalDateTime.now());sessions.insert(s);var trace=messages.selectByConversationIdAndTenantId(c.getId(),t);assertThat(trace).extracting(AiConversationMessageDO::getRole).containsExactly("USER","ASSISTANT");assertThat(sessions.selectByIdAndTenantId(s.getId(),t)).extracting(AiRealtimeSessionDO::getMode,AiRealtimeSessionDO::getModelId,AiRealtimeSessionDO::getInterruptCount).containsExactly("NATIVE",88L,1);assertThat(trace).allSatisfy(x->assertThat(x.getMetadataJson()).doesNotContain("apiKey","pcm","audio"));sessions.deleteById(s.getId());trace.forEach(x->messages.deleteById(x.getId()));conversations.deleteById(c.getId());}
private void add(long t,long c,String turn,String role,String content,Long model){AiConversationMessageDO m=new AiConversationMessageDO();m.setTenantId(t);m.setConversationId(c);m.setTurnId(turn);m.setRole(role);m.setContent(content);m.setModelId(model);m.setCreatedAt(LocalDateTime.now());messages.insert(m);}}
